public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s == null) continue;
        maxLen = Math.max(maxLen, s.length());
    }

    // Check from the largest possible length down to 1
    for (int len = maxLen; len >= 1; len--) {
        for (String s : strings) {
            if (s == null) continue;
            for (int i = 0; i <= s.length() - len; i++) {
                String substring = s.substring(i, i + len);
                String inverse = new StringBuilder(substring).reverse().toString();

                // Check if substring or its inverse is a substring of any string
                boolean found = false;
                for (String other : strings) {
                    if (other == null) continue;
                    if (other.contains(substring) || other.contains(inverse)) {
                        found = true;
                        break;
                    }
                }

                if (found) {
                    return len;
                }
            }
        }
    }

    return 0;
}
