public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                // Use DFS to mark all connected oil pockets as visited
                dfs(grid, i, j, rows, cols);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int i, int j, int rows, int cols) {
    // Base case: out of bounds or not an oil pocket
    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    // Mark as visited by changing to '*'
    grid[i][j] = '*';

    // Explore all 8 directions (up, down, left, right, and diagonals)
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int k = 0; k < 8; k++) {
        int newX = i + dx[k];
        int newY = j + dy[k];
        dfs(grid, newX, newY, rows, cols);
    }
}
