public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }

    // Check remainder 0: must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs of remainders
    for (int i = 1; i <= k / 2; i++) {
        int complement = (k - i) % k;
        if (i == complement) {
            // When i == k - i, i.e., 2*i == k, remainder must be even
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            // Count of remainder i must equal count of remainder (k-i)
            if (remainderCount[i] != remainderCount[complement]) {
                return false;
            }
        }
    }

    return true;
}
