public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == sum / n
    // => sum(subset) * n == sum * k
    // => sum(subset) == sum * k / n
    // So sum * k must be divisible by n.

    // We can use dynamic programming with bitsets.
    // dp[i][j] = true if we can pick j elements with sum i
    // But sum can be large, so we use a different approach.

    // Alternative: use a set of possible sums for each count.
    // Let's use a list of sets: sets[j] contains all possible sums of j elements.

    // To optimize, we can use a boolean array for each count, but sum might be large.
    // Let's use a HashSet for each count.

    // Actually, a more efficient approach is to use a bitset for each count.
    // But let's use a simpler approach with sets of integers.

    // We'll use an array of HashSets: possibleSums[j] = set of all possible sums of j elements.
    // Start with possibleSums[0] = {0}

    java.util.Set<Integer>[] possibleSums = new java.util.Set[n + 1];
    for (int i = 0; i <= n; i++) {
        possibleSums[i] = new java.util.HashSet<>();
    }
    possibleSums[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element twice
        for (int j = n; j >= 1; j--) {
            for (int s : possibleSums[j - 1]) {
                possibleSums[j].add(s + num);
            }
        }
    }

    // Now check for each k from 1 to n-1
    for (int k = 1; k < n; k++) {
        // Check if sum * k is divisible by n
        if (sum * k % n != 0) {
            continue;
        }
        int targetSum = sum * k / n;
        if (possibleSums[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}
