    if (s == null || s.length() < k) {
        return false;
    }

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    int mask = total - 1;
    int current = 0;

    for (int i = 0; i < s.length(); i++) {
        current = ((current << 1) | (s.charAt(i) - '0')) & mask;

