public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }

    // The array is [1, 3, 5, ..., 2n-1]
    // The target value is the average, which is n (since sum = n^2, average = n)
    // We need to compute the sum of absolute differences from n for the first half
    // For i from 0 to n/2 - 1, the value is 2*i + 1, and the difference is n - (2*i + 1)
    // The total operations is the sum of these differences (since each operation moves 1 unit)

    int operations = 0;
    for (int i = 0; i < n / 2; i++) {
        int value = 2 * i + 1;
        operations += n - value;
    }

    return operations;
}
