public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    // Handle edge case where low > high
    if (low > high) {
        return result;
    }

    // Check single digit numbers (0-9)
    for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
        result.add(i);
    }

    // Use BFS to generate stepping numbers with more than one digit
    // Start with digits 1-9 (0 is already handled)
    for (int i = 1; i <= 9; i++) {
        if (i > high) continue;
        // We already added single digit numbers, so we need to generate multi-digit ones
        // But we need to be careful not to add single digit numbers again
        // Let's use a different approach: generate all stepping numbers via BFS and filter
    }

    // Better approach: Use BFS to generate all stepping numbers up to high
    // Then filter those in [low, high]

    // Clear result and use BFS approach
    result.clear();

    // BFS queue to generate stepping numbers
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();

    // Start with digits 0-9
    for (int i = 0; i <= 9; i++) {
        if (i <= high) {
            queue.offer(i);
        }
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add(num);
        }

        // Get the last digit
        int lastDigit = num % 10;

        // Generate next numbers by adding lastDigit-1 and lastDigit+1
        if (lastDigit > 0) {
            int next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }

        if (lastDigit < 9) {
            int next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    // Sort the result to ensure ascending order
    java.util.Collections.sort(result);

    return result;
}
