        return 0;
    }

    int n = A.length;
    int[] count = new int[10001]; // Assuming values are within reasonable range
    for (int num : A) {
        if (num >= 0 && num < count.length) {
            count[num]++;
        }
    }

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquareSum = new boolean[10001][10001];
    for (int i = 0; i < 10001; i++) {
        for (int j = 0; j < 10001; j++) {
            int sum = i + j;
            int sqrt = (int) Math.sqrt(sum);
            isSquareSum[i][j] = (sqrt * sqrt == sum);
        }
    }

    // Use backtracking with memoization
    // State: (index, lastValue, remaining counts)
    // Since we can't easily memoize with counts, we'll use a different approach
    // We'll use DFS with pruning

    int[] result = {0};
    dfs(A, count, isSquareSum, -1, 0, n, result);

    return result[0];
}

private static void dfs(int[] A, int[] count, boolean[][] isSquareSum, int lastValue, int currentLength, int n, int[] result) {
    if (currentLength == n) {
        result[0]++;
        return;
    }

    for (int i = 0; i < count.length; i++) {
        if (count[i] == 0) continue;

        // Check if this value can be placed
        if (currentLength > 0 && !isSquareSum[lastValue][i]) {
            continue;
        }

        // To avoid counting duplicate permutations, we only place a value if:
        // 1. It's the first occurrence of this value in the current position, OR
        // 2. The previous value (i-1) has count 0 (meaning we've already used all of i-1)
        // Actually, a simpler approach: only place value i if count[i] > 0 and 
        // (i == 0 or count[i-1] == 0) to avoid duplicates
        if (i > 0 && count[i - 1] > 0) {
            continue;
        }

        count[i]--;
        dfs(A, count, isSquareSum, i, currentLength + 1, n, result);
        count[i]++;
    }
}
